import{c as t,Q as o,j as r,m as a}from"./chunks/framework.BqPkuuVc.js";const n="/assets/settings-hire-cards.Rj90khZg.png",s="/assets/settings-hire-cards-bulk-owner.Aeb3iMfs.png",i="/assets/settings-other-hire.CY5crf5s.png",h="/assets/add-competitor-hire-card.D_x9grLR.png",d="/assets/competitors-list-hire-card.WGjlLvAC.png",l="/assets/edit-competitor-hire-card.BdhSU6xA.png",c="/assets/edit-competitor-hire-items.BfxBZwOa.png",g="/assets/hire-items-view.sfSWpDi1.png",m="/assets/rego-hire-items.BP7T92zq.png",u="/assets/rego-hire-items-scrolled.C05-4KkZ.png",p="/assets/hire-item-return-prompt-card.DDtvD2FU.png",b="/assets/hire-item-return-prompt.BpcYILOJ.png",w="/assets/hire-item-return-prompt-compass.o25ZkQ3f.png",y="/assets/edit-event-hire-items.DqvIPUAs.png",A=JSON.parse('{"title":"Hire items","description":"","frontmatter":{},"headers":[],"relativePath":"user/running-the-event/hire-items.md","filePath":"user/running-the-event/hire-items.md"}'),f={name:"user/running-the-event/hire-items.md"};function v(k,e,q,T,_,x){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="hire-items" tabindex="-1">Hire items <a class="header-anchor" href="#hire-items" aria-label="Permalink to &quot;Hire items&quot;">​</a></h1><p><strong>Audience:</strong> Registration desk volunteers and timing operators lending equipment to competitors.</p><p>Almost every organiser lends something. <em>Hire cards</em> (rental cards) are the big one — SportIdent cards for newcomers, visitors, or the regular who left theirs on the kitchen table — and the same table usually has a box of compasses and a stack of map boards on it too. The job never changes: hand the right thing out, know who is holding it, and get it back before they drive home.</p><p>Manager tracks all of it. This page is mostly about hire cards, because that is most of what gets lent and it is the part Manager can do the most for; everything else you lend is covered from <a href="#everything-else-you-lend">Everything else you lend</a> onwards.</p><h2 id="how-hiring-works-in-manager" tabindex="-1">How hiring works in Manager <a class="header-anchor" href="#how-hiring-works-in-manager" aria-label="Permalink to &quot;How hiring works in Manager&quot;">​</a></h2><p>Everything you lend is set up <strong>once</strong>, in Settings, and shared by every event on this server. There are two registries, because the two kinds of thing reach a competitor differently:</p><table tabindex="0"><thead><tr><th></th><th><strong>Hire cards</strong></th><th><strong>Everything else</strong></th></tr></thead><tbody><tr><td>Set up in</td><td><strong>Settings → Hire card registry</strong></td><td><strong>Settings → Other hire registry</strong></td></tr><tr><td>What it is</td><td>A pool of card numbers</td><td>A list of named items — <em>Compass</em>, <em>Map board</em></td></tr><tr><td>How a competitor gets one</td><td>Automatic: they&#39;re &quot;on a hire card&quot; whenever the card number recorded against them is one of the pool numbers</td><td>Ticked on the competitor&#39;s own record</td></tr><tr><td>How it comes back</td><td>By itself, when the card is downloaded</td><td>Only when somebody takes it off the competitor</td></tr></tbody></table><p>Two consequences worth knowing before you start:</p><ul><li>Both registries are <strong>global</strong>. Set them up before your first event and they are there for every event afterwards.</li><li>Because being &quot;on a hire card&quot; is worked out from the pool, a card moves on and off hire by itself. Add a number to the pool and every competitor already carrying it is flagged retrospectively; take it out again and they go back to being treated as own-card. <strong>There is no &quot;hand out a hire card&quot; step to remember</strong> — you assign a hire card by recording its number as that competitor&#39;s card, exactly as you would their own.</li></ul><h2 id="set-up-your-hire-card-pool" tabindex="-1">Set up your hire-card pool <a class="header-anchor" href="#set-up-your-hire-card-pool" aria-label="Permalink to &quot;Set up your hire-card pool&quot;">​</a></h2><p>Do this once, before your first event, and again whenever you buy more cards.</p><ol><li>Open <strong>Settings → Hire card registry</strong>.</li><li>Add your card numbers. There are two ways, and you can mix them: <ul><li><strong>Quick add card numbers</strong> — type one or more numbers and/or ranges into the field and press <strong>Enter</strong> (or click <strong>Add</strong>). Separate them with commas or spaces, and write a range with a hyphen: <code>411001, 411002 411005</code> or <code>411001-411010</code>.</li><li><strong>Range from / Range to</strong> — enter the first and last number and click <strong>Add range</strong>. Handy for a contiguous batch straight out of the box.</li></ul></li><li>Everything you add is merged into the list, de-duplicated and sorted, so it does not matter if numbers overlap or arrive out of order.</li><li>Click <strong>Save</strong>. Until you do, an <strong>Unsaved — click Save below</strong> chip sits at the top as a reminder.</li></ol><p><img src="'+n+'" alt="The Settings → Hire card registry screen: a &quot;Quick add card numbers&quot; field with an Add button, &quot;Range from&quot; and &quot;Range to&quot; fields with an Add range button, a count of the pool alongside Clear all, and the cards listed below with an Owner column and a remove × on each row."></p><p>To take cards out again: the <strong>×</strong> at the end of a row removes one, ticking several rows gives you <strong>Remove selected</strong>, and <strong>Clear all</strong> empties the pool.</p><blockquote><p><strong>Tip:</strong> Hire cards usually come in a numbered run. Label the physical cards to match and enter them as one range (e.g. <code>411001-411050</code>), so the numbers in the box are the numbers in Manager.</p></blockquote><blockquote><p><strong>Note:</strong> Anything Manager cannot read — letters, zero or negative numbers, a backwards range — is listed back to you as ignored rather than being added silently. If a count looks wrong, read the message.</p></blockquote><h3 id="whose-cards-are-they" tabindex="-1">Whose cards are they? <a class="header-anchor" href="#whose-cards-are-they" aria-label="Permalink to &quot;Whose cards are they?&quot;">​</a></h3><p><strong>Owner</strong> is free text for whoever the physical card belongs to: the club it was borrowed from, or the person who wants it back at the end of the day. Leave it blank for cards with no particular owner. It travels with the pool, so it shows against that card in every event, and it appears on the <strong>Hire items</strong> screen and at the registration desk.</p><p>There are three ways to set it:</p><ul><li><strong>As you add</strong> — type into the <strong>Owner (optional)</strong> field next to <em>Quick add</em>. It is applied to every card you add (by quick add <em>or</em> by range) while that field has something in it, so a whole club&#39;s batch gets its owner in one go. Clear the field before adding cards that have no owner.</li><li><strong>In bulk</strong> — tick the checkbox on any rows, then use <strong>Set owner</strong> or <strong>Clear owner</strong> in the bar that appears above the table.</li><li><strong>One at a time</strong> — type straight into the <strong>Owner</strong> cell on a card&#39;s row.</li></ul><p><img src="'+s+'" alt="The hire-card registry with two rows ticked and a bar above the table reading &quot;2 selected&quot;, with an &quot;Owner for selected&quot; field and Set owner, Clear owner and Remove selected buttons."></p><h2 id="everything-else-you-lend" tabindex="-1">Everything else you lend <a class="header-anchor" href="#everything-else-you-lend" aria-label="Permalink to &quot;Everything else you lend&quot;">​</a></h2><p><strong>Settings → Other hire registry</strong> is the list of everything that is not a card. Click <strong>Add item</strong>, give it a name (<em>Compass</em>, <em>Map board</em>), and choose its shape:</p><ul><li><strong>Leave &quot;Individually numbered&quot; off</strong> when one is as good as another — a compass. Set <strong>How many you have</strong> if you want the desk to know how many are left in the box; leave it at 0 if you do not count them. Handing one out records only that the competitor has one.</li><li><strong>Turn &quot;Individually numbered&quot; on</strong> when each one carries its own number and you need to know <em>which</em> one went out, the way a card does. List the numbers in <strong>Item numbers</strong> — commas or spaces, and a range like <code>1-30</code> is expanded — and they appear as chips you can remove one at a time. You can leave the list empty: the item is still numbered, and the number is typed in as it is handed over.</li></ul><p><strong>Owner</strong> works as it does for cards, with one difference: it is per item rather than per unit, because a box of compasses came from one place. It shows in the <strong>Owner</strong> column of the Hire items screen and at the registration desk.</p><p>Use the arrows to reorder items — that is the order they appear in on a competitor&#39;s record — the <strong>×</strong> to remove one, and <strong>Save</strong> when you are done.</p><p><img src="'+i+'" alt="The Settings → Other hire registry screen: a Compass row owned by Southern Navigators with &quot;Individually numbered&quot; off and &quot;How many you have&quot; set to 20, and a Map board row with it on, an &quot;Item numbers&quot; field, and chips A1, A2, A3, A4."></p><blockquote><p><strong>Note:</strong> Removing an item only stops it being offered. Competitors already holding one keep it, so adding it back under the same name brings them back with it.</p></blockquote><h2 id="hand-a-card-over" tabindex="-1">Hand a card over <a class="header-anchor" href="#hand-a-card-over" aria-label="Permalink to &quot;Hand a card over&quot;">​</a></h2><p>A hire card is just a pool number recorded against a competitor, so you give one out the way you record any card:</p><ul><li><strong>At the registration desk</strong> — when entering or editing the competitor, type the hire card&#39;s number into <strong>Card number</strong>. See <a href="./../event-setup/competitors-clubs-teams">Competitors, clubs and teams</a> and <a href="./late-entries">Late entries</a>.</li><li><strong>On the fly at download</strong> — if somebody has run on a hire card that was never recorded, download the card and assign it to them in the usual way. See <a href="./card-download">Downloading cards</a>.</li></ul><p><img src="'+h+'" alt="The Add Competitor dialog with the Card number field filled in and a small &quot;Hire card&quot; caption directly beneath it, showing Manager has recognised the number as one from the pool."></p><p>As soon as the recorded number is one of your pool numbers, Manager flags it — you do not tell it anything:</p><ul><li>The <strong>Competitors</strong> list shows a small hire-card marker next to the number, and the <strong>Card type</strong> filter in the toolbar narrows the list to <strong>Hire card</strong> or <strong>Own card</strong>.</li><li>The <strong>Edit Competitor</strong> dialog shows a hire-card chip in its header and another beside the card field.</li></ul><p><img src="'+d+'" alt="The Competitors list with a &quot;Card type&quot; filter in the toolbar; a competitor&#39;s row shows their card number with a hire-card icon next to it."></p><p><img src="'+l+'" alt="The Edit Competitor dialog: a &quot;Hire card&quot; chip in the header beside the card chip, and a &quot;Hire card&quot; chip next to the Card number field."></p><p>To move somebody onto a different card mid-event, change their <strong>Card number</strong>. There is nothing hire-specific to undo first.</p><h2 id="hand-anything-else-over" tabindex="-1">Hand anything else over <a class="header-anchor" href="#hand-anything-else-over" aria-label="Permalink to &quot;Hand anything else over&quot;">​</a></h2><p>Other items are ticked on the competitor. Open them — from the Competitors list, from the registration desk, or by clicking their name on the Hire items screen — and go to the <strong>Hire items</strong> tab. The tab is there whenever the Other hire registry lists something.</p><p>Tick what they took. For a numbered item, pick the number you handed over from the list or type it in. A badge on the tab counts what they are holding.</p><p><img src="'+c+'" alt="The Edit Competitor dialog on its Hire items tab, headed &quot;Record what the competitor has hired&quot;: Compass ticked, and Map board ticked with a Number of A2."></p><h2 id="track-what-is-out-during-the-event" tabindex="-1">Track what is out during the event <a class="header-anchor" href="#track-what-is-out-during-the-event" aria-label="Permalink to &quot;Track what is out during the event&quot;">​</a></h2><p><strong>Event data → Hire items</strong> is the live picture of what has left the table. Two chips across the top count it:</p><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Out</strong></td><td>It is with a competitor and still has to come back.</td></tr><tr><td><strong>Returned</strong></td><td>The card has been downloaded, so it has been handed back and read. Only cards reach this state on their own.</td></tr></tbody></table><p>The table lists a row per thing that is out (and per card that has come back): the <strong>Item</strong> — a hire card, or one of your own items — its <strong>Number</strong>, the <strong>Owner</strong> you recorded, the <strong>Competitor</strong> holding it (click the name to open their record), the <strong>Status</strong>, and the <strong>Returned at</strong> time once a card has been downloaded. Use the search box to jump to one, or the <strong>Status</strong> and <strong>Item</strong> filters to narrow the list.</p><p><img src="'+g+'" alt="The Hire items view under Event data: chips reading &quot;Out: 5&quot; and &quot;Returned: 1&quot;, and a table listing compasses, map board A2 and hire cards against the competitors holding them."></p><blockquote><p><strong>Note:</strong> A card returned by one runner and then lent to a second appears as two rows — the first <strong>Returned</strong>, the second <strong>Out</strong> — so reusing a card for a later starter never makes the earlier runner look like they still have it.</p></blockquote><p>At the end of the day, filter to <strong>Out</strong> to see exactly what has not come back, and who has it.</p><h3 id="the-same-box-at-the-registration-desk" tabindex="-1">The same box, at the registration desk <a class="header-anchor" href="#the-same-box-at-the-registration-desk" aria-label="Permalink to &quot;The same box, at the registration desk&quot;">​</a></h3><p>The desk has its own view of the same thing, sized for a tablet: <strong>Hire items</strong> in the bottom bar of <a href="./late-entries">the registration desk</a>. It answers the two questions a desk actually asks — <em>what can I hand over</em>, and <em>who has the rest</em>:</p><ul><li>The <strong>Available</strong> and <strong>Out</strong> chips count the card pool, and they are also the filter. Tap one to see that half of the box; tap it again for all of it.</li><li>The search box takes a name, a card number or an item name. Putting a card on the desk&#39;s reader types its number in for you.</li><li>Your other items come first, one summary each: how many are out (of how many you have, if you said), and who is holding them. Compasses have no numbers to look up, so the desk&#39;s question about them is only ever &quot;have we got any left?&quot;.</li><li>Below the items is the card box itself, a row per card. Tapping anything that is out — a card, or a name under an item — opens the competitor holding it, so you can go and find them.</li></ul><p><img src="'+m+'" alt="The registration desk&#39;s Hire items screen on a tablet-width window: Available and Out chips and a search box pinned at the top, then a Compass summary owned by Southern Navigators reading &quot;8 of 20 out&quot; with the eight holders listed under it, and a Map board summary reading &quot;4 of 6 out&quot; with each holder&#39;s board number."></p><p><img src="'+u+'" alt="The same screen scrolled down to the card box: a row per hire card, the ones that are out showing the holder&#39;s name and an Out chip, the rest greyed with an Available chip."></p><blockquote><p><strong>Note:</strong> The desk reads a card as <strong>Available</strong> simply because nobody in this event is holding it, while the manager&#39;s Hire items screen reads a card as <strong>Returned</strong> because it was downloaded. The desk does no downloads, so it never claims a card came back — it only knows whether the card is out with somebody.</p></blockquote><h2 id="collect-it-all-back" tabindex="-1">Collect it all back <a class="header-anchor" href="#collect-it-all-back" aria-label="Permalink to &quot;Collect it all back&quot;">​</a></h2><p>A <strong>card</strong> counts as returned the moment it is downloaded; there is nothing to tick off by hand. <strong>Other items</strong> do not come back by themselves — nothing downloads a compass, so it stays out until somebody takes it off the competitor.</p><p>Manager brings both into a single prompt at download time. Download a card that is in the hire pool — or any card belonging to a competitor who has other hire items out — and a <strong>Collect hire items</strong> prompt lists everything to collect from that runner.</p><p><img src="'+p+'" alt="The collect prompt over the Download Card screen showing one row, &quot;Hire card&quot; with the card number beside it, &quot;From Jordan Lee&quot;, and a Collected button."></p><p>If they hired more than the card, it is still one prompt. Each row is the same size, whether or not the thing has a number on it:</p><p><img src="'+b+'" alt="The collect prompt listing three rows — Hire card with its number, Compass, and Map board A2 — under a &quot;From Jordan Lee&quot; line, with Not collected and Collected buttons."></p><p>And a competitor on their own card who borrowed a compass gets the prompt too, with no card row on it:</p><p><img src="'+w+'" alt="The collect prompt listing a single Compass row for a competitor running on their own card."></p><p>What the buttons do:</p><ul><li><strong>Collected</strong> takes those items off the competitor, so the Hire items screen stops chasing them. The card needs no action — downloading it was the return.</li><li><strong>Not collected</strong> leaves everything exactly as it was. That is the button for the runner who wanders off with the compass still in their hand.</li><li>When the only thing to collect is the card, <strong>Not collected</strong> is not offered: both buttons would do the same nothing.</li></ul><p>The prompt stays on screen until you answer it, so it cannot be clicked away by accident, and it appears wherever you are downloading — the Download Card screen, the dashboard tile, or any page of the open event.</p><blockquote><p><strong>Tip:</strong> If you lend nothing at a particular event and the prompt is just noise, turn it off for that event: <strong>Event details → Hire items</strong>, and switch off <strong>Show collect hire item warning on download</strong>. It is on by default, and the setting is per event, so your other events are unaffected.</p></blockquote><p><img src="'+y+'" alt="The Event details dialog on its Hire items tab, showing the &quot;Show collect hire item warning on download&quot; switch and the explanation beneath it."></p><h2 id="if-something-looks-wrong" tabindex="-1">If something looks wrong <a class="header-anchor" href="#if-something-looks-wrong" aria-label="Permalink to &quot;If something looks wrong&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What you see</th><th>Why</th><th>What to do</th></tr></thead><tbody><tr><td>A competitor&#39;s card shows no hire marker</td><td>That number is not in the pool</td><td>Add it in <strong>Settings → Hire card registry</strong>; the competitor is flagged as soon as you save</td></tr><tr><td>The Hire items screen says nothing has been set up</td><td>Both registries are empty</td><td>Fill in one or both — the screen reads them, not this event</td></tr><tr><td>No collect prompt on download</td><td>The event&#39;s switch is off, or that competitor has nothing on hire</td><td>Check <strong>Event details → Hire items</strong>, then the competitor&#39;s card number and their <strong>Hire items</strong> tab</td></tr><tr><td>An item vanished from the competitor&#39;s Hire items tab</td><td>The item was removed from the Other hire registry</td><td>Add it back under the same name and its holders come back with it</td></tr><tr><td>The desk shows a compass as out but nobody has it</td><td>Somebody took it back without it being recorded</td><td>Open the holder (tap their name) and untick it on their <strong>Hire items</strong> tab</td></tr><tr><td>A card still says <strong>Out</strong> at the end of the day</td><td>It has not been downloaded — the runner may not have come back through the finish</td><td>Chase the runner, and see <a href="./resolving-issues">Resolving issues</a> for a competitor who never downloaded</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../event-setup/competitors-clubs-teams">Competitors, clubs and teams</a></li><li><a href="./card-download">Downloading cards</a></li><li><a href="./late-entries">Late entries</a></li><li><a href="./resolving-issues">Resolving issues</a></li><li><a href="./../reference/settings">Settings</a></li><li><a href="./../event-setup/pre-event-checklist">Pre-event checklist</a></li></ul>',71)])])}const H=t(f,[["render",v]]);export{A as __pageData,H as default};
